import org.xml.sax.helpers.DefaultHandler;

public class XMLParsingExample {

    // Define the handler to process XML nodes
    private static class ParsingHandler extends DefaultHandler {
        private boolean isNameNode = false; // flag to check whether current node is <name> or not

        @Override
        public void startElement(String uri, String localName, String qName,
                               Attributes attributes) throws SAXException {
            if ("name".equals(qName)) { // at the start of a name element?
                isNameNode = true;
            }
        }

        @Override
        public void characters(char[] ch, int start, int length)
               throws SAXException {

            if (isNameNode) { // current node is a <name> node; so process its text content
                String nameValue = new String(ch, start, length);
                System.out.println("Name Value: "+nameValue.valueOf(nameValue));
            }
        }

        @Override
        public void endElement(String uri, String localName, String qName)
               throws SAXException {
            isNameNode = false; // reset the name flag as we're done processing <name> element
        } 
    }

    public static void main(String[] args) {

        try {  
            XMLInputFactory factory = XMLInputFactory.newInstance();  

            // Creating a stream reader using factory to parse the sample xml file.
            XMLStreamReader reader =  factory.createXMLStreamReader(new FileInputStream("sample.xml"));

            int event;
            while (reader.hasNext()) {
                event = reader.next();
                switch(event) {
                    case XMLEvent.START_ELEMENT:
                        System.out.println("Start Element: qName=" + reader.getLocalName());
                        break;
                    case XMLEvent.END_ELEMENT :
                        System.out.println("End Element: "+reader.getLocalName());
                        break; 
                    case XMLEvent.CHARACTERS : 
                        System.out.println("Characters: " + reader.getTextContent().trim());
                        break;
                }
            }  
        } catch(FXMLStreamException ex) {
            System.err.println(reader.getLocation() + " parse error at depth "+reader.getDepth());         
            StringWriter sw = new StringWriter(); 
            PrintWriter pw = new PrintWriter( sw );
            ex.printStackTrace(pw);
            System.out.println(sw.toString());
            ex.printStackTrace(); 
            return;  
        } catch(IOException io) {        
            io.printStackTrace();
            return;
        }

    }
}

